// Brand colors for CSS inline styling (provider icons)
const _BRAND_COLORS = {
  claude: '#D97706', openai: '#10a37f', gemini: '#4285F4', qwen: '#6F42C1',
  doubao: '#3B82F6', minimax: '#ef4444', deepseek: '#4D6BFE', grok: '#aaa',
  mistral: '#F7D046', glm: '#3859FF', yourprovider: '#FFC300', tsinghua: '#82318E',
  kimi: '#ccc', openrouter: '#6566F1', mimo: '#FF6A00', baiducloud: '#2932E1',
  shubiaobiao: '#E87A7A', bedrock: '#3D8FFF', hunyuan: '#0055E9', local: '#16a34a',
  vllm: '#30A2FF', sglang: '#A5300F', ollama: '#6B7280',
  generic: '#888',
};

const _BRAND_PATTERNS = [
  // ★ Aggregator platforms MUST be before individual model brands — they host
  //   Claude/GPT/etc. models, so the combined brand hint would match those first.
  [/yeysai|thunlp|tsinghua|清华/i,           'tsinghua'],
  [/example-corp|longcat|yourprovider|your-corp|your-mascot/i,     'yourprovider'],
  [/openrouter/i,                          'openrouter'],
  [/mimo|xiaomi/i,                         'mimo'],
  [/shubiaobiao|数标标/i,                      'shubiaobiao'],
  [/qianfan|ernie|baidu|wenxin|文心/i,       'baiducloud'],
  [/hunyuan|^hy\d|tencent|腾讯|混元/i,        'hunyuan'],
  // Bedrock must come before claude — Bedrock endpoints host Claude models
  // but the provider identity is AWS/Bedrock.
  [/bedrock|bedrock-runtime|amazonaws\.com\/openai|^us\.anthropic\.|^us\.amazon\.|amazon\.titan|amazon\.nova/i, 'bedrock'],
  // 'fable' = Anthropic Fable (Fable 5+): same Messages-API family as Claude,
  // so it must render with the Claude brand logo + amber color (backend already
  // treats it as Claude family — see lib/model_info/_family.is_claude).
  [/claude|anthropic|opus|sonnet|haiku|fable/i, 'claude'],
  [/gpt|openai|o[134]-|chatgpt|dall/i,   'openai'],
  [/gemini|gemma|palm|bard/i,             'gemini'],
  [/qwen|tongyi|qwq/i,                    'qwen'],
  [/doubao|seed.*pro|byte/i,              'doubao'],
  [/minimax|abab|m2-her/i,                  'minimax'],
  [/kimi|moonshot|月之暗面/i,                'kimi'],
  [/deepseek/i,                            'deepseek'],
  [/grok|xai/i,                            'grok'],
  [/mistral|mixtral|pixtral/i,             'mistral'],
  [/glm|zhipu|z\.ai|chatglm|bigmodel/i,   'glm'],
];

function _detectBrand(text) {
  if (!text) return 'generic';
  for (var i = 0; i < _BRAND_PATTERNS.length; i++) {
    if (/** @type {RegExp} */ (_BRAND_PATTERNS[i][0]).test(text)) return _BRAND_PATTERNS[i][1];
  }
  return 'generic';
}

/* ★ Short display name for a model_id — available globally for ui.js, main.js etc. */
function _modelShortName(modelId) {
  if (!modelId) return 'Model';
  if (typeof _modelPricingCache !== 'undefined' && _modelPricingCache && _modelPricingCache[modelId]) {
    var mp = _modelPricingCache[modelId];
    if (mp.name) return mp.name;
  }
  return modelId.replace(/^(aws\.|vertex\.)/, '').split('/').pop();
}


/* ★ Sort key for ordering a model list the way the user READS it.
 *
 * `_modelShortName` is not a pure function of model_id — it prefers
 * `_modelPricingCache[id].name`, and that cache is only populated once
 * /api/v1/server-config has returned `model_pricing`. Callers that run before
 * (or without) that fetch — the `.catch` fallback in
 * _loadServerConfigAndPopulate, a settings-close repaint on a failed load —
 * would otherwise sort by a DIFFERENT string than the one on screen. Falling
 * back to the same gateway-prefix-stripped id that _modelShortName itself
 * returns on a cache miss keeps the degraded order stable and near-identical
 * rather than arbitrary. */
function _modelDisplaySortKey(modelId) {
  var label = (typeof _modelShortName === 'function')
    ? _modelShortName(modelId)
    : String(modelId || '').replace(/^(aws\.|vertex\.)/, '').split('/').pop();
  // Fold -, _ and / to a space BEFORE collating. The collator weights a space
  // lower than a hyphen, so without this the SEPARATOR outranks the content and
  // a friendly name always beats a raw id that shares its prefix:
  // "Gemini 3.6 Flash" sorted before "gemini-3.1-flash-lite-preview", and
  // "MiniMax M3" before "MiniMax-M2.5". Since only models WITH a
  // MODEL_PRICING entry get a spaced label, the two spellings interleave in
  // every real list. Folding is sort-key-only — the rendered label keeps its
  // original punctuation, and numeric collation still sees the digit runs.
  return String(label == null ? '' : label).replace(/[-_\/]+/g, ' ');
}

/* Numeric-aware collator: plain `<`/`>` on lowercased strings orders
 * "Gemini 3.10" before "Gemini 3.5" and "Opus 4.10" before "Opus 4.6" —
 * wrong the moment a minor version reaches two digits. `numeric: true` compares
 * embedded digit runs as numbers. Built once; Intl.Collator construction is the
 * expensive part, not the compare. */
var _MODEL_NAME_COLLATOR = (typeof Intl !== 'undefined' && Intl.Collator)
  ? new Intl.Collator(undefined, { numeric: true, sensitivity: 'base' })
  : null;

/* ★ THE display-name comparator. Single source of truth for model ordering —
 * the toolbar picker (_populateModelDropdown) and the Settings cold sort
 * (_coldSortModels) both route through it so the two lists can never disagree.
 * Accepts a model_id string or a {model_id} entry. */
function _compareModelsByDisplayName(a, b) {
  var ka = _modelDisplaySortKey((a && a.model_id !== undefined) ? a.model_id : a);
  var kb = _modelDisplaySortKey((b && b.model_id !== undefined) ? b.model_id : b);
  if (_MODEL_NAME_COLLATOR) return _MODEL_NAME_COLLATOR.compare(ka, kb);
  var la = ka.toLowerCase(), lb = kb.toLowerCase();
  return la < lb ? -1 : (la > lb ? 1 : 0);
}


/* Sort a list of {model_id} entries in place by display name. Thin wrapper
 * around the comparator so callers never hand-roll one. */
function _sortModelsByDisplayName(models) {
  if (Array.isArray(models)) models.sort(_compareModelsByDisplayName);
  return models;
}

/* Same, for the `{model: {model_id}, provider}` shape _getAllModels() yields. */
function _sortModelEntriesByDisplayName(entries) {
  if (Array.isArray(entries)) {
    entries.sort(function(a, b) {
      return _compareModelsByDisplayName(a && a.model, b && b.model);
    });
  }
  return entries;
}

/* Order brand/provider group keys by the heading text actually rendered —
 * the brandNames[] label when there is one, else the group's provider name,
 * else the raw key. Callers previously used `for (var k in grouped)`, i.e.
 * insertion order, which is provider order in server_config.json and
 * unrelated to anything on screen. */
function _sortedBrandKeys(grouped, brandNames) {
  var keys = Object.keys(grouped || {});
  keys.sort(function(x, y) {
    var gx = grouped[x] || {}, gy = grouped[y] || {};
    var nx = ((brandNames && brandNames[x]) || gx.name || x);
    var ny = ((brandNames && brandNames[y]) || gy.name || y);
    return _compareModelsByDisplayName(String(nx), String(ny));
  });
  return keys;
}

/* ★ Friendly provider display name for a provider_id — used by the message
 * finish bar (route tag) to show which provider actually served a turn.
 * Resolves via the registered-models list (each carries provider_id +
 * provider_name), falling back to the raw id. */
function _providerDisplayName(providerId) {
  if (!providerId) return '';
  try {
    if (typeof _registeredModels !== 'undefined' && Array.isArray(_registeredModels)) {
      for (var i = 0; i < _registeredModels.length; i++) {
        var m = _registeredModels[i];
        if (m && m.provider_id === providerId && m.provider_name) return m.provider_name;
      }
    }
  } catch (e) { /* best-effort — fall back to the raw id */ }
  return providerId;
}

function _brandSvg(brand, size) {
  var s = size || 20;
  var svg = _BRAND_ICONS[brand] || _BRAND_ICONS.generic;
  var color = _BRAND_COLORS[brand] || _BRAND_COLORS.generic;
  return '<span class="stg-brand-icon" style="width:' + s + 'px;height:' + s + 'px;color:' + color + '">' + svg + '</span>';
}

// ── Tofu mascot avatars — all rendered as <img> referencing SVG files ──
// Each file in static/icons/ can be browsed/previewed directly.
// Planner/Critic/Worker are AI-generated PNGs converted to SVG via vtracer.
// Default agent and user (onigiri) are hand-crafted compact SVGs.
//
// Icon files:
//   tofu-planner.svg  — tofu with beret + clipboard (planner role)
//   tofu-critic.svg   — tofu with monocle + magnifying glass (critic role)
//   tofu-worker.svg   — tofu with hard hat + wrench (worker role)
//   onigiri.svg       — rice ball mascot (user avatar)
//
// Generate new icons: python3 scripts/gen_tofu_icons.py
// Convert PNG→SVG:    python3 scripts/png_to_svg.py

const _ICON_V = '20260402b';  // cache-bust version — bump when icons change
const _ICON_BASE = (typeof BASE_PATH!=='undefined'?BASE_PATH:'') + '/static/icons';

const _TOFU_PLANNER_SVG = `<img src="${_ICON_BASE}/tofu-planner.svg?v=${_ICON_V}" alt="Planner" style="width:100%;height:100%;display:block">`;
const _TOFU_CRITIC_SVG  = `<img src="${_ICON_BASE}/tofu-critic.svg?v=${_ICON_V}" alt="Critic" style="width:100%;height:100%;display:block">`;
const _TOFU_WORKER_SVG  = `<img src="${_ICON_BASE}/tofu-worker.svg?v=${_ICON_V}" alt="Worker" style="width:100%;height:100%;display:block">`;
const _USER_AVATAR_SVG  = `<img src="${_ICON_BASE}/onigiri.svg?v=${_ICON_V}" alt="You" style="width:100%;height:100%;display:block">`;


// ══════════════════════════════════════════════════════
//  Auto-initiated turn attribution — the INITIATOR_REGISTRY
// ══════════════════════════════════════════════════════
//
// Many backend paths inject a turn WITHOUT a human typing (Project Brain
// dispatch, proactive scheduler, timer continuation, swarm auto-continuation,
// peer / operator nudge, autopilot VU). Each stamps `_initiator` (authoritative)
// via lib/conversations/turn_initiation.py; older / not-yet-migrated messages
// carry only a legacy boolean. This registry is the SINGLE frontend source that
// maps an initiator → its avatar + header label + CSS class, so adding a new
// auto-source is one backend stamp + one row HERE (no renderer surgery).
//
// Glyphs are inline SVG (project rule §3.4: no emoji as icons). autopilot / peer
// / operator keep their EXISTING avatars/labels (already differentiated + test-
// pinned) — they live here too so the registry is complete, but chat_render.js
// keeps its dedicated arms for them; the NEW consumers are proactive / timer /
// brain (user lane) and swarm (assistant lane), which previously fell through
// to the onigiri "You" (proactive/timer/brain) or plain "Agent" (swarm).

// Distinct concept glyphs (14×14, currentColor) for the newly-attributed sources.
const _INIT_GLYPH_PROACTIVE =
  '<svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><circle cx="12" cy="12" r="9"/><path d="M13 7l-4 6h3l-1 4 4-6h-3z" fill="currentColor" stroke="none"/></svg>';
const _INIT_GLYPH_TIMER =
  '<svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M6 2h12M6 22h12"/><path d="M8 2c0 4 8 6 8 10s-8 6-8 10"/><path d="M16 2c0 4-8 6-8 10s8 6 8 10"/></svg>';
const _INIT_GLYPH_BRAIN =
  '<svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M9 3a3 3 0 0 0-3 3 3 3 0 0 0-1.5 5.6A3 3 0 0 0 6 17a3 3 0 0 0 3 3 2 2 0 0 0 2-2V5a2 2 0 0 0-2-2z"/><path d="M15 3a3 3 0 0 1 3 3 3 3 0 0 1 1.5 5.6A3 3 0 0 1 18 17a3 3 0 0 1-3 3 2 2 0 0 1-2-2V5a2 2 0 0 1 2-2z"/></svg>';
const _INIT_GLYPH_SWARM =
  '<svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><circle cx="12" cy="5" r="2.2"/><circle cx="5" cy="18" r="2.2"/><circle cx="19" cy="18" r="2.2"/><path d="M12 7.2v4.3M10.4 13l-3.6 3.2M13.6 13l3.6 3.2"/></svg>';

// initiator id → presentation. `avatar` is trusted markup (raw()'d by callers).
// `labelKey` resolves via i18n t(); `fallback` is the English default.
// `lane` documents which role the turn arrives as (user vs assistant).
const INITIATOR_REGISTRY = {
  proactive: { avatar: _INIT_GLYPH_PROACTIVE, labelKey: 'initiator.proactive', fallback: 'Proactive Agent', cls: 'init-proactive', lane: 'user' },
  timer:     { avatar: _INIT_GLYPH_TIMER,     labelKey: 'initiator.timer',     fallback: 'Timer',           cls: 'init-timer',     lane: 'user' },
  brain:     { avatar: _INIT_GLYPH_BRAIN,     labelKey: 'initiator.brain',     fallback: 'Project Brain',   cls: 'init-brain',     lane: 'user' },
  swarm:     { avatar: _INIT_GLYPH_SWARM,     labelKey: 'initiator.swarm',     fallback: 'Auto-continued',  cls: 'init-swarm',     lane: 'assistant' },
};

/**
 * Resolve WHO initiated a message — the ONE frontend read seam, mirroring the
 * backend lib/conversations/turn_initiation.resolve_initiator ONE-directionally:
 * prefer the authoritative `_initiator` field, else fall back to a legacy
 * per-path boolean (for pre-migration / persisted messages). Returns a plain
 * initiator string; 'human' for a normal input-box turn or any unknown shape.
 * @param {Object} msg
 * @returns {string}
 */
function _resolveInitiator(msg) {
  if (!msg || typeof msg !== 'object') return 'human';
  const v = msg._initiator;
  if (v === 'human' || INITIATOR_REGISTRY[v]
      || v === 'peer' || v === 'operator' || v === 'autopilot') {
    return v;
  }
  // Legacy fallback (most-specific pair first), matching the backend order.
  if (msg._peerMessage) return msg._peerHuman ? 'operator' : 'peer';
  if (msg._isVirtualUser || msg._autopilotRunId) return 'autopilot';
  if (msg._proactive) return 'proactive';
  if (msg._timer) return 'timer';
  if (msg._brainDispatch) return 'brain';
  if (msg._swarmAutoContinue) return 'swarm';
  return 'human';
}

/**
 * Presentation (avatar + label + cls) for a message's initiator, or null when
 * the initiator is 'human' / peer / operator / autopilot (those keep their
 * dedicated arms in chat_render.js). This is what the NEW attribution consumers
 * (proactive / timer / brain / swarm) read.
 * @param {Object} msg
 * @returns {{avatar:string,label:string,cls:string,lane:string,initiator:string}|null}
 */
function _initiatorPresentation(msg) {
  const id = _resolveInitiator(msg);
  const reg = INITIATOR_REGISTRY[id];
  if (!reg) return null;
  const label = (typeof t === 'function' && t(reg.labelKey) !== reg.labelKey)
    ? t(reg.labelKey) : reg.fallback;
  return { avatar: reg.avatar, label, cls: reg.cls, lane: reg.lane, initiator: id };
}

